-- مخطط D1 لتنبيهات واتساب. D1 متسق فورًا (على عكس KV): إلغاء الاشتراك يُرى مباشرة عند الإرسال التالي.
CREATE TABLE IF NOT EXISTS members (h TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, consent_at INTEGER, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS subs (h TEXT NOT NULL, show_id TEXT NOT NULL, title TEXT NOT NULL, since INTEGER NOT NULL, PRIMARY KEY (h, show_id));
CREATE TABLE IF NOT EXISTS outbox (h TEXT NOT NULL, ep_id TEXT NOT NULL, show_id TEXT NOT NULL, created INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (h, ep_id));
CREATE TABLE IF NOT EXISTS sent (h TEXT NOT NULL, ep_id TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (h, ep_id));
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);

-- الحسابات (Google): الدعوات، المستخدمون، الجلسات، رموز التحقق من الهاتف، والمزامنة لكل مستخدم
CREATE TABLE IF NOT EXISTS invites (email TEXT PRIMARY KEY, added INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created INTEGER NOT NULL, wa_prompt TEXT NOT NULL DEFAULT 'pending', phone TEXT, phone_verified_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions (h TEXT PRIMARY KEY, uid TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS otp (uid TEXT PRIMARY KEY, phone TEXT NOT NULL, code_h TEXT NOT NULL, expires INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sends INTEGER NOT NULL DEFAULT 1, window_start INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS favs (uid TEXT NOT NULL, show_id TEXT NOT NULL, on_flag INTEGER NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (uid, show_id));
CREATE TABLE IF NOT EXISTS prog (uid TEXT NOT NULL, key TEXT NOT NULL, show_id TEXT NOT NULL, ep_id TEXT NOT NULL, ep_num INTEGER, time REAL NOT NULL DEFAULT 0, duration REAL NOT NULL DEFAULT 0, done INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL, PRIMARY KEY (uid, key));
CREATE TABLE IF NOT EXISTS otp_log (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, uid TEXT NOT NULL, phone TEXT NOT NULL, ip TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS otp_log_at ON otp_log(at);
